			</Text>
			<Text color="gray">j/k or ↑/↓ = scroll, g = top, G = bottom, Ctrl+C = exit</Text>
			<Box height={1} />
			<VirtualizedList
				items={ITEMS}
				renderItem={(item) => <ItemBox item={item} />}
				overscan={5}
				height={28}
			/>
